"""Package the built data pack and publish it to Modrinth.

Every release is two Modrinth versions, the same way the web UI has always
uploaded it:

    5.1.17       the data pack zip, loader `datapack`
    5.1.17+mod   the same pack in a jar with Fabric / Quilt / Forge / NeoForge
                 metadata, so it can go in a mods folder and apply to every world

The web UI generates that jar itself ("Generated by Modrinth"); the API does
not, so this script builds it from the same metadata the web UI wrote.

Usage (from the repository root, after `./gradlew koreBuild` in redstone_additions/):

    python3 .github/scripts/modrinth_publish.py 5.1.17 [--dry-run]

Environment:
    MODRINTH_TOKEN   personal access token with the "Create versions" scope
    GAME_VERSIONS    space-separated Minecraft versions, e.g. "26.3"

A version number that already exists on Modrinth is skipped rather than
uploaded twice, so re-running a half-failed workflow is safe.

Standard library only, like discord_notify.py: nothing to install.
"""

import argparse
import io
import json
import os
import re
import sys
import urllib.error
import urllib.request
import uuid
import zipfile
from pathlib import Path
from typing import NoReturn

PROJECT_ID = "52z5jQjy"
API = "https://api.modrinth.com/v2"
USER_AGENT = "AnCarsenat/Redstone-Additions publish workflow"

ROOT = Path(__file__).resolve().parents[2]
KORE = ROOT / "redstone_additions"
# What `./gradlew koreBuild` writes: <outputDirectory>/<packName>.
PACK = KORE / "build" / "kore" / "redstone_additions"
CHANGELOG = KORE / "CHANGELOG.md"
GRADLE_PROPERTIES = KORE / "gradle.properties"

MOD_LOADERS = ["fabric", "forge", "neoforge", "quilt"]
MOD_ID = "mr_redstone_additions"
NAME = "Redstone Additions"
AUTHOR = "Ancar"
LICENSE = "LicenseRef-AMDL-v1"
ICON = "redstone-additions_pack.png"
HOMEPAGE = "https://modrinth.com/datapack/redstone-additions"
SOURCES = "https://github.com/AnCarsenat/Redstone-Additions"
ISSUES = SOURCES + "/issues"
DESCRIPTION = (
    "Best redstone&tech datapack, Super optimized, 55+ blocks\n"
    "(Block breaker, block placer, filters, conveyors, item pipes, breeder, "
    "generators, gates, chunk loader, wireless redstone, multiblocks, jetpacks "
    "and so much more ! )"
)


def fail(message: str) -> NoReturn:
    print(f"::error::{message}", file=sys.stderr)
    sys.exit(1)


# ---------------------------------------------------------------------------
# Checks and inputs
# ---------------------------------------------------------------------------


def declared_version() -> str:
    """`version` in redstone_additions/gradle.properties: the one place it is written."""
    for line in GRADLE_PROPERTIES.read_text(encoding="utf-8").splitlines():
        match = re.match(r"\s*version\s*=\s*(\S+)", line)
        if match:
            return match.group(1)
    fail(f"no version= line in {GRADLE_PROPERTIES.relative_to(ROOT)}")


def description_text(part) -> str:
    """A pack.mcmeta description: a string, a text component, or a list of either."""
    if isinstance(part, str):
        return part
    if isinstance(part, list):
        return "".join(description_text(p) for p in part)
    if isinstance(part, dict):
        return part.get("text", "") + "".join(description_text(p) for p in part.get("extra", []))
    return ""


def check_pack_version(version: str) -> None:
    """gradle.properties and the built pack.mcmeta must both name the version being published."""
    declared = declared_version()
    if declared != version:
        fail(
            f"publishing {version}, but {GRADLE_PROPERTIES.relative_to(ROOT)} says "
            f"version={declared}. Bump it and rebuild before tagging."
        )
    mcmeta_path = PACK / "pack.mcmeta"
    if not mcmeta_path.is_file():
        fail(f"{mcmeta_path.relative_to(ROOT)} not found; run ./gradlew koreBuild first")
    mcmeta = json.loads(mcmeta_path.read_text(encoding="utf-8"))
    text = description_text(mcmeta["pack"]["description"])
    if not re.search(rf"\bv{re.escape(version)}(?![0-9A-Za-z.-])", text):
        fail(
            f"pack.mcmeta says {text.strip()!r}, not v{version}. "
            "Bump the version and rebuild before tagging."
        )


def changelog(version: str) -> str:
    """The CHANGELOG.md section for this version, heading included."""
    text = CHANGELOG.read_text(encoding="utf-8")
    match = re.search(
        rf"^## \[v{re.escape(version)}\].*?(?=^## \[v|\Z)", text, re.M | re.S
    )
    if not match:
        fail(f"no '## [v{version}]' section in {CHANGELOG.relative_to(ROOT)}")
    return match.group(0).strip() + "\n"


# ---------------------------------------------------------------------------
# Packaging
# ---------------------------------------------------------------------------


def pack_files() -> list[tuple[str, bytes]]:
    files = []
    for path in sorted(PACK.rglob("*")):
        if path.is_file() and "__pycache__" not in path.parts:
            files.append((path.relative_to(PACK).as_posix(), path.read_bytes()))
    return files


def zip_bytes(entries: list[tuple[str, bytes]]) -> bytes:
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as archive:
        for name, data in entries:
            archive.writestr(name, data)
    return buffer.getvalue()


def toml_mods(version: str, loader: str, loader_version: str, update_url: str) -> str:
    description = json.dumps(DESCRIPTION)  # a TOML basic string escapes like JSON
    return f"""
modLoader = '{loader}'
loaderVersion = '{loader_version}'
license = '{LICENSE}'
showAsResourcePack = false
mods = [
\t{{ modId = '{MOD_ID}', version = '{version}', displayName = '{NAME}', description = {description}, logoFile = '{ICON}', updateJSONURL = '{update_url}', credits = 'Generated by Modrinth', authors = '{AUTHOR}', displayURL = '{HOMEPAGE}' }},
]
issueTrackerURL = '{ISSUES}'
"""


def mod_metadata(version: str, icon: bytes) -> list[tuple[str, bytes]]:
    contact = {"homepage": HOMEPAGE, "sources": SOURCES, "issues": ISSUES}
    fabric = {
        "schemaVersion": 1,
        "id": MOD_ID,
        "version": version,
        "name": NAME,
        "description": DESCRIPTION,
        "authors": [AUTHOR],
        "contact": contact,
        "license": LICENSE,
        "icon": ICON,
        "environment": "*",
        "depends": {"fabric-resource-loader-v0": "*"},
    }
    quilt = {
        "schema_version": 1,
        "quilt_loader": {
            "group": "com.modrinth",
            "id": MOD_ID,
            "version": version,
            "metadata": {
                "name": NAME,
                "description": DESCRIPTION,
                "contributors": {AUTHOR: "Member"},
                "contact": contact,
                "icon": ICON,
            },
            "intermediate_mappings": "net.fabricmc:intermediary",
            "depends": [
                {
                    "id": "quilt_resource_loader",
                    "versions": "*",
                    "unless": "fabric-resource-loader-v0",
                }
            ],
        },
    }
    updates = f"https://api.modrinth.com/updates/{PROJECT_ID}/forge_updates.json"
    return [
        ("fabric.mod.json", json.dumps(fabric, ensure_ascii=False).encode()),
        ("quilt.mod.json", json.dumps(quilt, ensure_ascii=False).encode()),
        (
            "META-INF/mods.toml",
            toml_mods(version, "lowcodefml", "[40,)", updates).encode(),
        ),
        (
            "META-INF/neoforge.mods.toml",
            toml_mods(version, "javafml", "[1,)", updates + "?neoforge=only").encode(),
        ),
        (ICON, icon),
    ]


# ---------------------------------------------------------------------------
# Modrinth API
# ---------------------------------------------------------------------------


def request(method: str, url: str, token: str | None = None, body=None, headers=None):
    headers = {"User-Agent": USER_AGENT, **(headers or {})}
    if token:
        headers["Authorization"] = token
    req = urllib.request.Request(url, data=body, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=120) as response:
            return json.loads(response.read() or b"null")
    except urllib.error.HTTPError as error:
        fail(f"{method} {url} -> {error.code}: {error.read().decode(errors='replace')}")


def existing_versions() -> set[str]:
    versions = request("GET", f"{API}/project/{PROJECT_ID}/version")
    return {v["version_number"] for v in versions}


def upload(token: str, data: dict, filename: str, content: bytes, mime: str) -> dict:
    boundary = uuid.uuid4().hex
    parts = [
        f'--{boundary}\r\nContent-Disposition: form-data; name="data"\r\n'
        "Content-Type: application/json\r\n\r\n".encode()
        + json.dumps(data).encode()
        + b"\r\n",
        f'--{boundary}\r\nContent-Disposition: form-data; name="file"; '
        f'filename="{filename}"\r\nContent-Type: {mime}\r\n\r\n'.encode()
        + content
        + b"\r\n",
        f"--{boundary}--\r\n".encode(),
    ]
    return request(
        "POST",
        f"{API}/version",
        token,
        b"".join(parts),
        {"Content-Type": f"multipart/form-data; boundary={boundary}"},
    )


# ---------------------------------------------------------------------------


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("version", help='e.g. "5.1.17", without the leading v')
    parser.add_argument("--dry-run", action="store_true", help="package, do not upload")
    parser.add_argument("--out", type=Path, help="also write the packages here")
    args = parser.parse_args()
    version = args.version

    if not re.fullmatch(r"[0-9A-Za-z.-]+", version):
        fail(f"refusing version {version!r}: letters, digits, dots and hyphens only")
    game_versions = os.environ.get("GAME_VERSIONS", "").split()
    if not game_versions:
        fail("GAME_VERSIONS is empty")

    check_pack_version(version)
    notes = changelog(version)

    files = pack_files()
    icon = (PACK / "pack.png").read_bytes()
    packages = [
        {
            "version_number": version,
            "loaders": ["datapack"],
            "filename": f"redstone_additions_v{version}(RELEASE)-0000.zip",
            "content": zip_bytes(files),
            "mime": "application/zip",
        },
        {
            "version_number": f"{version}+mod",
            "loaders": MOD_LOADERS,
            "filename": f"redstone-additions-{version}.jar",
            "content": zip_bytes(files + mod_metadata(version, icon)),
            "mime": "application/java-archive",
        },
    ]

    if args.out:
        args.out.mkdir(parents=True, exist_ok=True)
        for package in packages:
            (args.out / package["filename"]).write_bytes(package["content"])

    print(f"Redstone Additions {version} for {', '.join(game_versions)}")
    for package in packages:
        size = len(package["content"]) / 1024
        print(f"  {package['version_number']:<14} {package['filename']} ({size:.0f} KiB)")
    if args.dry_run:
        print("dry run: nothing uploaded")
        return

    token = os.environ.get("MODRINTH_TOKEN")
    if not token:
        fail("MODRINTH_TOKEN secret is not set")

    already = existing_versions()
    for package in packages:
        number = package["version_number"]
        if number in already:
            print(f"  {number}: already on Modrinth, skipped")
            continue
        data = {
            "project_id": PROJECT_ID,
            "name": f"{NAME} {version}",
            "version_number": number,
            "changelog": notes,
            "dependencies": [],
            "game_versions": game_versions,
            "version_type": "release",
            "loaders": package["loaders"],
            "featured": False,
            "status": "listed",
            "file_parts": ["file"],
            "primary_file": "file",
        }
        result = upload(token, data, package["filename"], package["content"], package["mime"])
        print(f"  {number}: published https://modrinth.com/datapack/redstone-additions/version/{result['id']}")


if __name__ == "__main__":
    main()
